/** Runs every step in order. */
export async function runFlow(page: Page, vars: Vars): Promise<Outputs> {
  const outputs: Outputs = {};
  await page.goto('http://127.0.0.1:3000/');
  await steps['01-open'](page, { v1: 'http://127.0.0.1:3000/' }, outputs);
  await steps['02-create'](page, { d1: '', d2: '', v1: vars.runid, v2: `${vars.runid} Availability`, v3: `${vars.runid} Bench Dashboard` }, outputs);
  await steps['03-add'](page, { v3: vars.runid, v4: `${vars.runid} Bench Dashboard`, v5: `http://127.0.0.1:3000/d/${outputs['02-create.url.p1'] ?? ''}/${vars.runid}-bench-dashboard`, v6: `${vars.runid} Notes`, v7: `Notes for run ${vars.runid}` }, outputs);
  await steps['04-add'](page, { v1: `${vars.runid} Bench Dashboard`, v3: outputs['02-create.url.p1'] ?? '', v4: `${vars.runid}-bench-dashboard` }, outputs);
  await steps['05-report'](page, { v1: `${vars.runid} Bench Dashboard`, v6: `${vars.runid} Notes`, v7: `http://127.0.0.1:3000/d/${outputs['02-create.url.p1'] ?? ''}/${vars.runid}-bench-dashboard` }, outputs);
  return outputs;
}
